/* Pearns Point lot geometry.

   Extracted from Studio RHE drawing M01, "Pearns Point Site Plan", 1:2000, by
   reading the PDF's own vector data — no tracing. The drawing encodes each
   lot's April-2023 status in its fill colour (green available, sand sold), and
   separates lot numbers from contour elevations by whether the digit sits
   inside one of RHE's 133 yellow label boxes.

   Areas follow the live site's own area tabs, extended to cover the sold lots
   those tabs leave out. Statuses and prices come from the August 2026 price
   list, plus lots 1-9 Reserved and 17/18 Sold.

   This ships as a static module for the preview page. Moving it into Sanity is
   a matter of seeding these same fields onto lotsSitePlanPage.lots[] and
   swapping the import in the page for a fetch — the component takes the data
   as a prop precisely so that is a one-line change.

   Coordinates are in the SVG viewBox below, not pixels. `lx`/`ly` are the
   pole of inaccessibility (the point furthest from any edge) rather than the
   centroid, and `r` is that distance — which is what sizes the number so it
   fits inside its lot. */

export type LotStatus = 'available' | 'reserved' | 'sold'

export interface Lot {
  /** null for the merged block, which covers several lots in one shape */
  n: number | null
  area: string
  status: LotStatus
  /** SVG path data */
  d: string
  lx: number
  ly: number
  r: number
  sq?: number
  rate?: number
  price?: number
  view?: string
  /** the lot numbers a merged shape covers */
  group?: number[]
  /** how a shape's lots divide between areas, for counting */
  tally?: [string, number][]
}

export const VIEW_BOX = { w: 1700, h: 1142 }

/** The site's tab order runs round the peninsula, not alphabetically. */
export const AREA_ORDER = [
  'Oceans Edge', 'Five Islands Point', 'Pearns Bay', 'North Beach', 'Secret Bay',
  'Five Islands Bay', 'Pearns Beach', 'Five Islands View', 'The Look Out',
]

